function chime(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const c=new A(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(660,c.currentTime);o.frequency.exponentialRampToValueAtTime(880,c.currentTime+.16);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.035,c.currentTime+.03);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.35);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.36);o.onended=()=>c.close()}catch{}}
function settings(){const d=$('dset');if(!d||$('novaSSettings'))return;const w=document.createElement('div');w.id='novaSSettings';w.innerHTML='<h4>Nova Experience</h4><label class="sw"><input id="novaData" type="checkbox"><span>Data Saver / Lite mode</span></label><label class="sw"><input id="novaSound" type="checkbox"><span>Startup chime (off by default)</span></label><label class="sw"><input id="novaFest" type="checkbox"><span>Festival greetings (off by default)</span></label><label>Accent palette <select id="novaAccent"><option value="saffron">Saffron</option><option value="peacock">Peacock</option><option value="ganga">Ganga</option></select></label>';d.append(w);$('novaData').checked=!!prefs.dataSaver;$('novaSound').checked=!!prefs.sound;$('novaFest').checked=!!prefs.festivals;$('novaAccent').value=prefs.accent;$('novaData').onchange=x=>{prefs.dataSaver=x.target.checked;save();location.reload()};$('novaSound').onchange=x=>{prefs.sound=x.target.checked;save();if(prefs.sound)chime()};$('novaFest').onchange=x=>{prefs.festivals=x.target.checked;save()};$('novaAccent').onchange=x=>{prefs.accent=x.target.value;save();accent()}}
