function ambientAtmosphere(){
 if($('novaAtmosphere'))return;
 const host=document.createElement('div');host.id='novaAtmosphere';host.setAttribute('aria-hidden','true');
 host.innerHTML='<span class="nova-aurora a"></span><span class="nova-aurora b"></span><span class="nova-aurora c"></span><span class="nova-atmo-grid"></span><canvas></canvas>';
 document.body.prepend(host);
 const canvas=host.querySelector('canvas'),ctx=canvas?.getContext('2d',{alpha:true,desynchronized:true});if(!ctx||lite())return;
 let w=0,h=0,raf=0,particles=[],last=0,visible=true;
 const count=()=>Math.max(12,Math.min(25,Math.round((w*h)/52000)));
 const resize=()=>{const d=Math.min(window.devicePixelRatio||1,1.15);w=window.innerWidth;h=window.innerHeight;canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);particles=Array.from({length:count()},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.11,vy:(Math.random()-.5)*.1,r:.55+Math.random()*1.15,p:Math.random()*6.28}))};
 const draw=now=>{raf=0;if(!visible||document.hidden)return;if(now-last<32){raf=requestAnimationFrame(draw);return}last=now;ctx.clearRect(0,0,w,h);
  for(let i=0;i<particles.length;i++){const p=particles[i];p.x+=p.vx;p.y+=p.vy;p.p+=.006;if(p.x<0)p.x=w;if(p.x>w)p.x=0;if(p.y<0)p.y=h;if(p.y>h)p.y=0;const alpha=.18+.16*(.5+.5*Math.sin(p.p));ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(205,190,255,'+alpha+')';ctx.fill();
   for(let j=i+1;j<particles.length;j++){const q=particles[j],dx=p.x-q.x,dy=p.y-q.y,dist=dx*dx+dy*dy;if(dist<105*105){ctx.strokeStyle='rgba(130,177,190,'+(.055*(1-Math.sqrt(dist)/105))+')';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}}
  }raf=requestAnimationFrame(draw)};
 const start=()=>{if(!raf&&visible&&!document.hidden)raf=requestAnimationFrame(draw)};
 const stop=()=>{if(raf)cancelAnimationFrame(raf);raf=0};
 const observer=new IntersectionObserver(()=>{},{});observer.disconnect();
 const onVisibility=()=>{visible=!document.hidden;if(visible)start();else stop()};
 document.addEventListener('visibilitychange',onVisibility,{passive:true});
 window.addEventListener('resize',()=>{resize();start()},{passive:true});
 resize();start();
}
function livingCore(){
 coreObservers.forEach(o=>o.disconnect());coreObservers=[];clearTimeout(coreTimer);
 const root=$('novaLivingCore');if(!root)return;
 const setState=state=>{if(root.isConnected&&root.dataset.state!==state)root.dataset.state=state};
 const live=$('live');
 if(live){const sync=()=>{const c=String(live.className||'');setState(c.includes('ls-listen')?'listening':c.includes('ls-think')?'thinking':c.includes('ls-speak')?'speaking':'idle')};const observer=new MutationObserver(sync);observer.observe(live,{attributes:true,attributeFilter:['class']});coreObservers.push(observer);sync()}
 const messages=$('msgs');
 if(messages){const observer=new MutationObserver(records=>{const added=records.flatMap(r=>Array.from(r.addedNodes)).filter(n=>n.nodeType===1);const assistant=added.some(n=>n.matches?.('.m.a')||n.querySelector?.('.m.a'));const user=added.some(n=>n.matches?.('.m.u')||n.querySelector?.('.m.u'));if(!assistant&&!user)return;setState(assistant?'speaking':'thinking');clearTimeout(coreTimer);coreTimer=setTimeout(()=>setState('idle'),2800)});observer.observe(messages,{childList:true,subtree:true});coreObservers.push(observer)}
 if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>root.classList.toggle('n-core-paused',!entries[0]?.isIntersecting),{threshold:.05});observer.observe(root);coreObservers.push(observer)}
 if(lite())root.classList.add('n-core-lite');
}
